  /* ---------- Promotions ---------- */
  function renderTahfeezPromotion(){ const source=$("tahfeezPromotionSource")?.value||"", rows=state.tahfeezRows.filter(r=>r.tahfeez_class===source); const wrap=$("tahfeezTransitionTargetWrap"); if(wrap)wrap.classList.toggle("hidden",source!=="TAHFEEZ5"); state.selectedTahfeezPromotion=new Set([...state.selectedTahfeezPromotion].filter(id=>rows.some(r=>academyId(r)===id))); setHTML("tahfeezPromotionStudents",rows.length?rows.map(row=>`<label class="promotion-student"><input type="checkbox" data-tahfeez-promo="${esc(academyId(row))}" ${state.selectedTahfeezPromotion.has(academyId(row))?"checked":""}><span><strong>${esc(row.full_name)}</strong><small>${esc(regularId(row)||academyId(row))}</small></span><em>${esc(row.tahfeez_class_label)}</em></label>`).join(""):'<div class="table-empty">No students in this class.</div>'); updatePromotionButtons(); }
