  async function promoteTahfeez(){ const source=$("tahfeezPromotionSource").value, dest=source==="TAHFEEZ5"?$("tahfeezTransitionTarget").value:""; if(source==="TAHFEEZ5"&&!dest){toast("Choose the Islamiyyah destination for Tahfeez 5.","error");return;} try{const data=await api("/api/islamiyah/tahfeez/promote",{method:"POST",body:JSON.stringify({session:state.cfg.academic_session,term:state.cfg.term,source_class:source,destination_class:dest,admission_numbers:[...state.selectedTahfeezPromotion]})});toast(data.message);state.selectedTahfeezPromotion.clear();await Promise.all([loadTahfeez(),loadIslamiyahRoster(),loadConfig()]);renderTahfeezPromotion();}catch(e){toast(e.message,"error");} }
