  /* ---------- Academy roster management ---------- */
  function fillAcademyStudentClass(school,current=""){ const rows=school==="tahfeez"?tahfeezClasses():islamClasses(),el=$("academyStudentClass");if(!el)return;fillSelect(el,rows,"Select Academy class…","key","label",false);if(current&&[...el.options].some(o=>o.value===current))el.value=current; }
  function openStudentModal(school,row=null){ state.editingSchool=school;state.editingAdmission=row?academyId(row):"";const modal=$("academyStudentModal");if(!modal)return;$("academyStudentSchool").value=school;$("academyStudentSchool").disabled=true;$("academyStudentAdmission").value=row?academyId(row):"";$("academyStudentAdmission").readOnly=!!row;$("academyStudentLastName").value=row?.last_name||"";$("academyStudentFirstName").value=row?.first_name||"";$("academyStudentOtherNames").value=row?.other_names||"";$("academyStudentSex").value=row?.sex||"";$("academyStudentPhone").value=row?.phone||"";$("academyStudentRegularAdmission").value=regularId(row)||"";fillAcademyStudentClass(school,row?(school==="tahfeez"?row.tahfeez_class:row.islamiyah_class):"");setText("academyStudentModalEyebrow",school==="tahfeez"?"TAHFEEZ DATABASE":"ISLAMIYYAH DATABASE");setText("academyStudentModalTitle",row?`Edit ${row.full_name||academyId(row)}`:`Add ${school==="tahfeez"?"Tahfeez":"Islamiyyah"} Student`);$("academyStudentModalHint").textContent=regularId(row)?"This Academy profile is linked to Basic School. Edits here do not alter the original Students & Classes record.":"Independent Academy record. Leave Academy ID blank to generate the next ID automatically.";modal.classList.add("open");modal.setAttribute("aria-hidden","false");document.body.classList.add("academy-modal-open"); }
  function closeAcademyModal(which){const modal=which==="basic"?$("academyBasicRegisterModal"):$("academyStudentModal");if(modal){modal.classList.remove("open");modal.setAttribute("aria-hidden","true");}if(!document.querySelector(".academy-modal.open"))document.body.classList.remove("academy-modal-open");}
  async function saveAcademyStudent(){const school=state.editingSchool||$("academyStudentSchool")?.value||"islamiyah",payload={session:state.cfg.academic_session,term:state.cfg.term,school,admission_number:$("academyStudentAdmission")?.value||"",regular_admission_number:$("academyStudentRegularAdmission")?.value||"",last_name:$("academyStudentLastName")?.value||"",first_name:$("academyStudentFirstName")?.value||"",other_names:$("academyStudentOtherNames")?.value||"",sex:$("academyStudentSex")?.value||"",phone:$("academyStudentPhone")?.value||""};payload[school==="tahfeez"?"tahfeez_class":"islamiyah_class"]=$("academyStudentClass")?.value||"";if(!payload[school==="tahfeez"?"tahfeez_class":"islamiyah_class"]){toast("Choose an Academy class.","error");return;}const btn=$("saveAcademyStudent");if(btn)btn.disabled=true;try{const url=state.editingAdmission?`/api/islamiyah/roster/student/${encodeURIComponent(state.editingAdmission)}`:"/api/islamiyah/roster/student",method=state.editingAdmission?"PUT":"POST",data=await api(url,{method,body:JSON.stringify(payload)});toast(data.message||"Academy student saved.");closeAcademyModal("student");if(school==="tahfeez")await loadTahfeez();else await loadIslamiyahRoster();await loadConfig();}catch(e){toast(e.message,"error");}finally{if(btn)btn.disabled=false;}}
  function findAcademyRow(school,admission){return (school==="tahfeez"?state.tahfeezRows:state.islamiyahRows).find(row=>academyId(row)===admission);}
  async function removeAcademyStudents(school,ids){ids=[...new Set(ids||[])].filter(Boolean);if(!ids.length)return;const note=school==="islamiyah"?"Islamiyyah removal deactivates the current Academy roster record and preserves score history.":"Tahfeez removal removes the Tahfeez placement.";if(!confirm(`Remove ${ids.length} selected ${school==="tahfeez"?"Tahfeez":"Islamiyyah"} record(s)?\n\n${note}\nThe Basic School database will NOT be changed.`))return;try{const data=await api("/api/islamiyah/roster/students",{method:"DELETE",body:JSON.stringify({session:state.cfg.academic_session,term:state.cfg.term,school,admission_numbers:ids})});toast(data.message||"Academy records removed.");if(school==="tahfeez"){state.selectedTahfeez.clear();await loadTahfeez();}else{state.selectedRoster.clear();await loadIslamiyahRoster();}await loadConfig();}catch(e){toast(e.message,"error");}}
  async function moveTahfeezSelected(){const target=$("tahfeezMoveTarget")?.value||"";if(!target){toast("Choose the Tahfeez destination class.","error");return;}try{const data=await api("/api/islamiyah/tahfeez/assign",{method:"PUT",body:JSON.stringify({session:state.cfg.academic_session,term:state.cfg.term,tahfeez_class:target,admission_numbers:[...state.selectedTahfeez]})});toast(data.message||"Tahfeez placement updated.");state.selectedTahfeez.clear();await Promise.all([loadTahfeez(),loadConfig()]);}catch(e){toast(e.message,"error");}}
