  async function quickPromote(school,ids){ids=[...ids];const selection=sameClassSelected(school,ids);if(!selection.source){toast("Select students from one Academy class at a time before promoting.","error");return;}if(school==="tahfeez"){if(selection.source==="TAHFEEZ5"){openTab("promotions");$("tahfeezPromotionSource").value=selection.source;state.selectedTahfeezPromotion=new Set(ids);renderTahfeezPromotion();toast("Tahfeez 5 requires an Islamiyyah destination. Complete the promotion in the Promotion workspace.","warning");return;}try{const data=await api("/api/islamiyah/tahfeez/promote",{method:"POST",body:JSON.stringify({session:state.cfg.academic_session,term:state.cfg.term,source_class:selection.source,admission_numbers:ids})});toast(data.message);state.selectedTahfeez.clear();await Promise.all([loadTahfeez(),loadConfig()]);}catch(e){toast(e.message,"error");}return;}try{const data=await api("/api/islamiyah/promote",{method:"POST",body:JSON.stringify({session:state.cfg.academic_session,term:state.cfg.term,source_class:selection.source,admission_numbers:ids})});toast(data.message);state.selectedRoster.clear();await Promise.all([loadIslamiyahRoster(),loadConfig()]);}catch(e){toast(e.message,"error");}}

  /* ---------- Register Basic School students into Academy ---------- */
