  function existingRegularLinks(school){const rows=school==="tahfeez"?state.tahfeezRows:state.islamiyahRows;return new Set(rows.map(regularId).filter(Boolean).map(norm));}
  function renderBasicRegisterRows(){const school=$("basicRegisterSchool")?.value||state.basicRegisterSchool,links=existingRegularLinks(school),rows=state.basicRegisterRows;setText("basicRegisterVisibleCount",`${rows.length} students`);setText("basicRegisterSelectedCount",state.basicRegisterSelected.size);setHTML("basicRegisterBody",rows.length?rows.map((row,i)=>{const admission=row.regular_admission_number||row.admission_number,linked=links.has(norm(admission));return `<tr class="${linked?"already-linked":""}"><td class="check-col"><input type="checkbox" data-basic-register-check="${esc(admission)}" ${state.basicRegisterSelected.has(admission)?"checked":""}></td><td>${i+1}</td><td><span class="id-badge regular">${esc(admission)}</span></td><td class="student-name">${esc(row.full_name)}</td><td>${esc(row.sex||"—")}</td><td>${classBadge(row.class_arm||row.regular_class||"—")}</td><td>${linked?'<span class="status-badge linked">Already linked</span>':'<span class="status-badge">Available</span>'}</td></tr>`;}).join(""):'<tr><td colspan="7" class="table-empty">No Basic School students match this view.</td></tr>');const all=$("basicRegisterSelectAll"),visible=rows.map(row=>row.regular_admission_number||row.admission_number);if(all){all.checked=!!visible.length&&visible.every(id=>state.basicRegisterSelected.has(id));all.indeterminate=visible.some(id=>state.basicRegisterSelected.has(id))&&!all.checked;}if($("registerBasicSelected"))$("registerBasicSelected").disabled=!state.basicRegisterSelected.size||!$("basicRegisterTarget")?.value;}
  async function registerBasicSelected(){const school=$("basicRegisterSchool")?.value||state.basicRegisterSchool,target=$("basicRegisterTarget")?.value||"";if(!target){toast("Choose the destination Academy class.","error");return;}if(!state.basicRegisterSelected.size){toast("Select at least one Basic School student.","error");return;}const btn=$("registerBasicSelected");if(btn)btn.disabled=true;try{const data=await api("/api/islamiyah/roster/register-regular",{method:"POST",body:JSON.stringify({session:state.cfg.academic_session,term:state.cfg.term,school,class_level:target,admission_numbers:[...state.basicRegisterSelected]})});toast(data.message||"Students registered.");state.basicRegisterSelected.clear();if(school==="tahfeez")await loadTahfeez();else await loadIslamiyahRoster();await loadConfig();await loadBasicRegisterRows();}catch(e){toast(e.message,"error");}finally{if(btn)btn.disabled=false;renderBasicRegisterRows();}}

  /* ---------- Academy audit ---------- */
